// Correct known generated-name collisions. Domain matches still take priority.
Object.assign(NAME_TO_SLUG, {
  framer: 'framer',
  perplexity: 'perplexity',
})


function normalizeHost(domain?: string | null): string {
  if (!domain) return ''
  return domain
    .replace(/^(https?:\/\/)?(www\.)?/i, '')
    .split('/')[0]
    .toLowerCase()
    .trim()
}

function normalizeName(name?: string | null): string {
  if (!name) return ''
  return name
    .toLowerCase()
    .trim()
    .replace(/^by\s+/, '')
    .replace(/\s*\(ex\.[^)]+\)/gi, '')
    .replace(/\s+/g, ' ')
}

/**
 * Safe brand slug resolution.
 * Domain match preferred. Name match is exact / suffix-stripped / word-boundary (len>=5).
 * Never use short substring includes (caused YouTube→Google Cloud, NYT→new.png).
 */
function resolveBrandSlug(
  name?: string | null,
  domain?: string | null
): string | null {
  const host = normalizeHost(domain)
  if (host) {
    if (DOMAIN_TO_SLUG[host]) return DOMAIN_TO_SLUG[host]
    const parts = host.split('.')
    for (let i = 0; i < parts.length - 1; i++) {
      const candidate = parts.slice(i).join('.')
      if (DOMAIN_TO_SLUG[candidate]) return DOMAIN_TO_SLUG[candidate]
    }
    const base = parts[0]
    if (base && SLUG_FILE[base]) return base
  }

  const n = normalizeName(name)
  if (!n) return null

  if (NAME_TO_SLUG[n]) return NAME_TO_SLUG[n]

  const stripped = n
    .replace(
      /\s+(accelerator|incubator|program|fellowship|labs?|ventures?|premium|student|students|for startups|startups?)$/i,
      ''
    )
    .trim()
  if (stripped && NAME_TO_SLUG[stripped]) return NAME_TO_SLUG[stripped]

  const keys = Object.keys(NAME_TO_SLUG)
    .filter((k) => k.length >= 5)
    .sort((a, b) => b.length - a.length)
  for (const key of keys) {
    const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const re = new RegExp('(?:^|\\s)' + escaped + '(?:\\s|$)', 'i')
    if (re.test(n)) return NAME_TO_SLUG[key]
  }

  const compact = n.replace(/[^a-z0-9]/g, '')
  if (compact && SLUG_FILE[compact]) return compact
  if (compact && NAME_TO_SLUG[compact]) return NAME_TO_SLUG[compact]

  return null
}

/** Slugs that have a real /brand-logos/*.svg (do not invent paths for missing SVGs). */
/**
 * Prefer SVG only when the local SVG is the true multi-color / correct brand mark.
 * Do NOT prefer single-fill simple-icons that misrepresent multi-color brands.
 * Figma/OpenAI/Intercom: PNG or curated SVG handled via SLUG_FILE + chain order.
 */
const SLUGS_WITH_SVG = new Set([
  'airtable',
  'anthropic',
  'apple',
  'auth0',
  'autodesk',
  'cloudflare',
  'datadog',
  'digitalocean',
  'dropbox',
  'figma', // multi-color official paths
  'framer',
  'github',
  'googlecloud',
  'hubspot',
  'intercom', // classic chat mark (not Fin cyan wordmark)
  'jetbrains',
  'linear',
  'mongodb',
  'notion',
  'openai', // official black monochrome bloom (NOT green)
  'slack',
  'spotify',
  'stripe',
  'supabase',
  'threads',
  'unity',
  'vercel',
  'webflow',
  'ycombinator',
  'zoom',
])

/** Same-origin logo path(s). Prefer official SVG mark when present (colored brand). */
export function getLocalBrandLogoCandidates(
  name?: string | null,
  domain?: string | null
): string[] {
  const slug = resolveBrandSlug(name, domain)
  if (!slug) return []
  const file = SLUG_FILE[slug]
  if (!file) return []
  const base = file.replace(/\.(png|svg|webp|jpg|jpeg)$/i, '')
  const paths: string[] = []
  // Prefer crisp colored SVG when we actually have the file
  if (SLUGS_WITH_SVG.has(slug) || SLUGS_WITH_SVG.has(base)) {
    paths.push(`/brand-logos/${base}.svg`)
  }
  paths.push(`/brand-logos/${file}`)
  return [...new Set(paths)]
}

export function resolveLocalBrandSlug(
  name?: string | null,
  domain?: string | null
): string | null {
  return resolveBrandSlug(name, domain)
}
